import React, { useState } from 'react';
import Reservas from './Reservas';
import Eventos from './Eventos';
import Promociones from './Promociones';

const AdminPanel = () => {
  const [activeTab, setActiveTab] = useState('Reservas');

  return (
    <div style={{ display: 'flex', minHeight: '100vh' }}>
      {/* ... sidebar igual que antes ... */}
      <aside className="sidebar">
        {/* ... (tu código anterior de sidebar aquí) ... */}
        <ul className="nav-menu">
          {['Reservas', 'Eventos', 'Promociones'].map((tab) => (
            <li key={tab} className={`nav-item ${activeTab === tab ? 'active' : ''}`} onClick={() => setActiveTab(tab)}>
              {tab}
            </li>
          ))}
        </ul>
      </aside>

      <main className="main-content">
        {/* ... topbar igual ... */}
        <div className="dashboard-content">
          {activeTab === 'Reservas' && <Reservas />}
          {activeTab === 'Eventos' && <Eventos />}
          {activeTab === 'Promociones' && <Promociones />}
        </div>
      </main>
    </div>
  );
};
export default AdminPanel;
